const MODEL = $env.CLAUDE_MODEL || 'claude-opus-5-5';
const EFFORT = $env.CLAUDE_EFFORT || 'low';

function claudeRequest(system, userText, schema, maxTokens = 16000) {
  return {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    fallbacks: 'default',
    output_config: { effort: EFFORT, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: userText }],
  };
}

function parseClaude(resp) {
  if (!resp || resp.error) throw new Error('API error: ' + JSON.stringify(resp && resp.error).slice(0, 500));
  if (resp.stop_reason === 'refusal') throw new Error('refused: ' + JSON.stringify(resp.stop_details));
  if (resp.stop_reason === 'max_tokens') throw new Error('output truncated at max_tokens');
  const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  return JSON.parse(text);
}

const SYSTEM = "You are a product strategist for a demand-intelligence business in Calgary, Canada. We find\nconsumer demand and sell or refer it to manufacturers and merchants for a commission. We never\nhold inventory ourselves.\n\nYou receive clusters of pain points collected over the last 30 days. For each cluster, rate\nfive dimensions from 0 to 10, where higher is always better for us:\n- demand: how many people, how strong the intent, how many different sources.\n- margin: likely retail price CAD 30-150 with room for at least 65% gross margin when made in China.\n- gap: existing products clearly fail this need (complaints about current options count here).\n- logistics: small and light, under about 1 kg, not fragile, not liquid.\n- compliance: low regulatory risk in Canada. Score low for children's products, food, cosmetics,\n  medical claims, lithium batteries, radio transmitters, and anything needing CSA or Health Canada\n  approval.\n\nThen write a short brief a manufacturer could act on: who the buyer is, the problem in their own\nwords, what a good product must do, a target retail price range in CAD, and the evidence.\nOnly use evidence present in the input. Be concrete; skip clusters that are clearly not products by\ngiving them low scores rather than omitting them. Write titles and briefs in English.";
const SCHEMA = {"type": "object", "properties": {"opportunities": {"type": "array", "items": {"type": "object", "properties": {"cluster_key": {"type": "string"}, "title": {"type": "string"}, "demand": {"type": "integer"}, "margin": {"type": "integer"}, "gap": {"type": "integer"}, "logistics": {"type": "integer"}, "compliance": {"type": "integer"}, "target_price_cad": {"type": "string"}, "brief_md": {"type": "string"}}, "required": ["cluster_key", "title", "demand", "margin", "gap", "logistics", "compliance", "target_price_cad", "brief_md"], "additionalProperties": false}}}, "required": ["opportunities"], "additionalProperties": false};

const clusters = $input.all().map(i => i.json).filter(c => c.cluster_key);
if (!clusters.length) return [];
const brief = clusters.map(({ evidence_urls, ...c }) => c);  // 链接不发给模型，留作证据
return [{ json: { request: claudeRequest(SYSTEM, 'Clusters:\n' + JSON.stringify(brief, null, 1), SCHEMA) } }];

